{
  "task_id": "sca_ecc_ladder_conditional_add_timing_001",
  "domain_id": "side_channel_fault_analysis",
  "title": "Conditional point-addition timing in a scalar-multiplication controller",
  "description": "Analyze the cycle-timing and control-flow behavior of a small double-and-add scalar-multiplication controller across different input scalars, and propose an RTL remediation that equalizes timing while preserving correct outputs.",
  "input_artifacts": [
    "inputs/scalar_mult_ctrl.v",
    "inputs/field_datapath.v",
    "inputs/fault_model.md",
    "inputs/design_brief.md"
  ],
  "submission_artifacts": [
    "submission/vulnerability_report.json"
  ],
  "expected_output": {
    "path": "submission/vulnerability_report.json",
    "summary": "A single JSON report describing the scalar-dependent control path, per-bit cycle-timing signature across representative scalars, and a concrete RTL remediation that equalizes cycle count while preserving correct scalar-multiplication results."
  },
  "metrics": [
    {
      "name": "leakage_detection_accuracy",
      "description": "Whether the report correctly identifies the scalar-dependent control state/signal responsible for the timing variation and supports this with cycle-count data correlated to the scalar's Hamming weight."
    },
    {
      "name": "fault_coverage",
      "description": "Fraction of required cycle_counts_by_scalar entries (spanning low, mid, and high Hamming-weight scalars) that are present and numerically consistent with an independent simulation of the provided controller."
    },
    {
      "name": "hardening_precision",
      "description": "Whether the proposed remediation concretely describes always executing the conditional operation with a discarded/dummy result and selecting the real result via a mux, and whether correctness preservation is asserted and justified."
    },
    {
      "name": "format_conformance",
      "description": "Whether vulnerability_report.json satisfies the required JSON schema, with all fields present and of the correct type."
    }
  ],
  "toolchain": [
    "iverilog",
    "vvp",
    "yosys"
  ]
}

// =============================================================================
// scalar_mult_ctrl.v
//
// Double-and-add controller for a compact scalar-multiplication datapath.
//
// Processes a 16-bit scalar from bit index 15 down to bit index 0. For each
// bit index, the controller always performs a DOUBLE operation on the
// running accumulator. If the current scalar bit is 1, the controller also
// performs an ADD operation (accumulating a fixed base point into the
// running accumulator) before moving on to the next bit index. If the
// current scalar bit is 0, the controller proceeds directly to the next
// bit index without performing an ADD.
//
// Debug/analysis ports (state, cycle_count, cycle_count_valid) are provided
// purely to make the controller's internal behavior observable during
// simulation; they are not part of the production interface.
// =============================================================================

module scalar_mult_ctrl (
    input  wire        clk,
    input  wire        rst_n,        // active-low, synchronous reset
    input  wire        start,        // 1-cycle pulse while idle
    input  wire [15:0] scalar,       // MSB-first; bit 15 processed first

    output reg         done,         // 1-cycle Moore pulse
    output reg  [63:0] result_x,
    output reg  [63:0] result_y,

    // Debug / analysis-only outputs
    output reg  [2:0]  state,
    output reg  [15:0] cycle_count,
    output reg         cycle_count_valid
);

    // -------------------------------------------------------------------
    // FSM state encoding
    // -------------------------------------------------------------------
    localparam S_IDLE      = 3'd0;
    localparam S_DOUBLE    = 3'd1;
    localparam S_ADD       = 3'd2;
    localparam S_NEXT_BIT  = 3'd3;
    localparam S_DONE      = 3'd4;

    // -------------------------------------------------------------------
    // Internal registers
    // -------------------------------------------------------------------
    reg  [4:0]  bit_idx;       // 0..15, signed use via wrap; -1 detected via underflow flag
    reg         bit_idx_valid; // true while bit_idx is a valid 0..15 index

    reg  [63:0] acc_x, acc_y;      // running accumulator (result of DOUBLE/ADD chain)
    reg  [63:0] base_x, base_y;    // fixed base point fed to ADD

    // Handshake with field_datapath
    reg         dp_op_start;
    reg         dp_op_is_add;
    reg  [63:0] dp_in_x, dp_in_y;
    reg  [63:0] dp_add_x, dp_add_y;
    wire [63:0] dp_out_x, dp_out_y;
    wire        dp_op_done;

    wire cur_bit = bit_idx_valid ? scalar[bit_idx[3:0]] : 1'b0;

    // -------------------------------------------------------------------
    // Fixed base point used for ADD (illustrative constant, not secret)
    // -------------------------------------------------------------------
    localparam [63:0] BASE_X = 64'h0000_0000_0000_0005;
    localparam [63:0] BASE_Y = 64'h0000_0000_0000_0007;

    // -------------------------------------------------------------------
    // field_datapath instance: shared DOUBLE/ADD execution unit
    // -------------------------------------------------------------------
    field_datapath u_datapath (
        .clk       (clk),
        .rst_n      (rst_n),
        .op_start   (dp_op_start),
        .op_is_add  (dp_op_is_add),
        .in_x       (dp_in_x),
        .in_y       (dp_in_y),
        .add_x      (dp_add_x),
        .add_y      (dp_add_y),
        .out_x      (dp_out_x),
        .out_y      (dp_out_y),
        .op_done    (dp_op_done)
    );

    // -------------------------------------------------------------------
    // Main sequential FSM
    // -------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n) begin
            state             <= S_IDLE;
            done              <= 1'b0;
            result_x          <= 64'd0;
            result_y          <= 64'd0;
            cycle_count       <= 16'd0;
            cycle_count_valid <= 1'b0;

            bit_idx           <= 5'd0;
            bit_idx_valid     <= 1'b0;

            acc_x             <= 64'd0;
            acc_y             <= 64'd0;
            base_x            <= 64'd0;
            base_y            <= 64'd0;

            dp_op_start       <= 1'b0;
            dp_op_is_add      <= 1'b0;
            dp_in_x           <= 64'd0;
            dp_in_y           <= 64'd0;
            dp_add_x          <= 64'd0;
            dp_add_y          <= 64'd0;
        end else begin
            // done and cycle_count_valid are pulsed for exactly one cycle
            done              <= 1'b0;
            cycle_count_valid <= 1'b0;
            dp_op_start       <= 1'b0;

            case (state)

                // -----------------------------------------------------
                S_IDLE: begin
                    if (start) begin
                        // Seed accumulator with an identity-like starting
                        // point and the fixed base point for ADD.
                        acc_x         <= 64'd1;
                        acc_y         <= 64'd1;
                        base_x        <= BASE_X;
                        base_y        <= BASE_Y;

                        bit_idx       <= 5'd15;
                        bit_idx_valid <= 1'b1;

                        cycle_count   <= 16'd1;

                        // Kick off DOUBLE for bit 15
                        dp_op_start   <= 1'b1;
                        dp_op_is_add  <= 1'b0;
                        dp_in_x       <= 64'd1;
                        dp_in_y       <= 64'd1;
                        dp_add_x      <= BASE_X;
                        dp_add_y      <= BASE_Y;

                        state         <= S_DOUBLE;
                    end
                end

                // -----------------------------------------------------
                // DOUBLE is performed unconditionally for every bit index.
                S_DOUBLE: begin
                    cycle_count <= cycle_count + 16'd1;

                    if (dp_op_done) begin
                        acc_x <= dp_out_x;
                        acc_y <= dp_out_y;

                        if (cur_bit) begin
                            // Scalar bit is set: perform the ADD operation
                            // this bit index.
                            dp_op_start  <= 1'b1;
                            dp_op_is_add <= 1'b1;
                            dp_in_x      <= dp_out_x;
                            dp_in_y      <= dp_out_y;
                            dp_add_x     <= base_x;
                            dp_add_y     <= base_y;
                            state        <= S_ADD;
                        end else begin
                            // Scalar bit is clear: skip ADD entirely and
                            // proceed directly to the next bit index.
                            state <= S_NEXT_BIT;
                        end
                    end
                end

                // -----------------------------------------------------
                // ADD is performed only when the current scalar bit is 1.
                S_ADD: begin
                    cycle_count <= cycle_count + 16'd1;

                    if (dp_op_done) begin
                        acc_x <= dp_out_x;
                        acc_y <= dp_out_y;
                        state <= S_NEXT_BIT;
                    end
                end

                // -----------------------------------------------------
                S_NEXT_BIT: begin
                    cycle_count <= cycle_count + 16'd1;

                    if (bit_idx == 5'd0) begin
                        // Just processed bit index 0; nothing left to do.
                        bit_idx_valid <= 1'b0;
                        state         <= S_DONE;
                    end else begin
                        bit_idx <= bit_idx - 5'd1;

                        // Kick off DOUBLE for the next bit index.
                        dp_op_start  <= 1'b1;
                        dp_op_is_add <= 1'b0;
                        dp_in_x      <= acc_x;
                        dp_in_y      <= acc_y;
                        dp_add_x     <= base_x;
                        dp_add_y     <= base_y;

                        state <= S_DOUBLE;
                    end
                end

                // -----------------------------------------------------
                S_DONE: begin
                    result_x          <= acc_x;
                    result_y          <= acc_y;
                    done              <= 1'b1;
                    cycle_count_valid <= 1'b1;
                    state             <= S_IDLE;
                end

                default: begin
                    state <= S_IDLE;
                end

            endcase
        end
    end

endmodule

// =============================================================================
// field_datapath.v
//
// Multi-cycle field datapath shared by the scalar-multiplication controller.
// Implements two operations on a pair of 64-bit coordinate registers:
//
//   - DOUBLE (op_is_add == 0): produces a new (out_x, out_y) derived only
//     from (in_x, in_y). Takes DBL_CYCLES clock cycles to complete.
//
//   - ADD    (op_is_add == 1): produces a new (out_x, out_y) derived from
//     (in_x, in_y) and (add_x, add_y). Takes ADD_CYCLES clock cycles to
//     complete (intentionally more cycles than DOUBLE to model a more
//     complex operation).
//
// The arithmetic used here is a simplified, deterministic placeholder for a
// real elliptic-curve field operation: it combines the inputs with fixed
// shift/add/xor steps modulo a fixed constant so that results are
// reproducible and easy to check against a reference computation. It is not
// intended to model a specific curve.
// =============================================================================

module field_datapath (
    input  wire        clk,
    input  wire        rst_n,      // active-low, synchronous reset

    input  wire        op_start,   // 1-cycle pulse to begin an operation
    input  wire        op_is_add,  // 0 = DOUBLE, 1 = ADD (sampled at op_start)

    input  wire [63:0] in_x,
    input  wire [63:0] in_y,
    input  wire [63:0] add_x,      // used only when op_is_add == 1
    input  wire [63:0] add_y,      // used only when op_is_add == 1

    output reg  [63:0] out_x,
    output reg  [63:0] out_y,
    output reg          op_done     // 1-cycle pulse when result is valid
);

    // -------------------------------------------------------------------
    // Fixed latency for each operation kind.
    // -------------------------------------------------------------------
    localparam [3:0] DBL_CYCLES = 4'd3;
    localparam [3:0] ADD_CYCLES = 4'd4;

    // Fixed modulus-like constant used to keep intermediate values bounded.
    localparam [63:0] FIELD_MOD = 64'hFFFF_FFFF_FFFF_FFC5;

    // -------------------------------------------------------------------
    // Internal state
    // -------------------------------------------------------------------
    localparam S_IDLE = 1'b0;
    localparam S_BUSY = 1'b1;

    reg         busy_state;
    reg         latched_is_add;
    reg  [63:0] latched_in_x, latched_in_y;
    reg  [63:0] latched_add_x, latched_add_y;
    reg  [3:0]  cycle_ctr;
    reg  [3:0]  target_cycles;

    // -------------------------------------------------------------------
    // Combinational result computation (simplified deterministic update)
    // -------------------------------------------------------------------
    reg [63:0] comb_out_x;
    reg [63:0] comb_out_y;

    always @* begin
        if (latched_is_add) begin
            // ADD-style update: combine both point representations.
            comb_out_x = (latched_in_x + add_x + (latched_in_y ^ add_y)) % FIELD_MOD;
            comb_out_y = ((latched_in_y + add_y) ^ (latched_in_x + add_x)) % FIELD_MOD;
        end else begin
            // DOUBLE-style update: combine a point representation with itself.
            comb_out_x = ((latched_in_x << 1) + latched_in_y) % FIELD_MOD;
            comb_out_y = ((latched_in_y << 1) ^ latched_in_x) % FIELD_MOD;
        end
    end

    // -------------------------------------------------------------------
    // Sequential control
    // -------------------------------------------------------------------
    always @(posedge clk) begin
        if (!rst_n) begin
            busy_state     <= S_IDLE;
            op_done        <= 1'b0;
            out_x          <= 64'd0;
            out_y          <= 64'd0;

            latched_is_add <= 1'b0;
            latched_in_x   <= 64'd0;
            latched_in_y   <= 64'd0;
            latched_add_x  <= 64'd0;
            latched_add_y  <= 64'd0;

            cycle_ctr      <= 4'd0;
            target_cycles  <= 4'd0;
        end else begin
            op_done <= 1'b0;

            case (busy_state)

                S_IDLE: begin
                    if (op_start) begin
                        latched_is_add <= op_is_add;
                        latched_in_x   <= in_x;
                        latched_in_y   <= in_y;
                        latched_add_x  <= add_x;
                        latched_add_y  <= add_y;

                        target_cycles  <= op_is_add ? ADD_CYCLES : DBL_CYCLES;
                        cycle_ctr      <= 4'd1;

                        busy_state     <= S_BUSY;
                    end
                end

                S_BUSY: begin
                    if (cycle_ctr >= target_cycles) begin
                        out_x      <= comb_out_x;
                        out_y      <= comb_out_y;
                        op_done    <= 1'b1;
                        busy_state <= S_IDLE;
                    end else begin
                        cycle_ctr <= cycle_ctr + 4'd1;
                    end
                end

                default: begin
                    busy_state <= S_IDLE;
                end

            endcase
        end
    end

endmodule
